const KEY='readingPasture.v1';
const SETTINGS='readingPasture.settings';
const defaultState=()=>({readings:structuredClone(STARTER_READINGS),progress:{},history:[],learnedVocab:{},lastReading:null,streak:0,lastStudyDate:null});
let state=loadState();
let settings=Object.assign({theme:'light',music:true,sfx:true},JSON.parse(localStorage.getItem(SETTINGS)||'{}'));
let view='home', currentId=null, answers={}, hintsUsed={}, checked=false;
const app=document.getElementById('app'),modal=document.getElementById('modal'),modalBody=document.getElementById('modalBody'),toastEl=document.getElementById('toast');
document.documentElement.dataset.theme=settings.theme;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch(e){toast('Storage is full. Export your data and remove old items.')}}
function loadState(){try{let x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&Array.isArray(x.readings))return x}catch(e){}return defaultState()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),1800);sfx('tick')}
const LEVELS={1:{name:'Seedling',icon:'🌱',desc:'Short, direct texts. Find explicit information.'},2:{name:'Meadow',icon:'🌾',desc:'Everyday texts with main ideas, sequence and simple inference.'},3:{name:'Shepherd',icon:'🐑',desc:'Longer passages with purpose, reference and evidence-based inference.'},4:{name:'Wolf Trail',icon:'🐺',desc:'Extended reading, competing claims and deeper inference.'}};
function stats(){let done=Object.keys(state.progress).filter(k=>state.progress[k]?.attempts>0).length;let pts=0,max=0;Object.values(state.progress).forEach(p=>{pts+=p.points||0;max+=p.maxPoints||0});let acc=max?Math.round(pts/max*100):0;let vocab=Object.keys(state.learnedVocab).length;return{done,acc,vocab}}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));if(view==='home')home();else if(view==='practice')practiceHub();else if(view==='reading')readingView();else if(view==='bank')bankView();else if(view==='vocab')vocabView();else progressView();updateControls()}
function updateControls(){document.getElementById('themeBtn').textContent=settings.theme==='light'?'☀':'☾';document.getElementById('musicBtn').classList.toggle('active',settings.music);document.getElementById('sfxBtn').classList.toggle('active',settings.sfx)}
function home(){let s=stats();app.innerHTML=`<section class="hero"><div class="hero-card hero-copy"><div class="eyebrow">Morning English · Reading Training</div><h1>Read calmly.<br><em>Catch the wolf.</em></h1><p>Train detail, main idea, sequence, vocabulary in context, reference, purpose and inference. Every answer can be checked against textual evidence.</p><div class="hero-actions"><button class="btn primary" id="dailyBtn">▶ Start a reading</button><button class="btn" data-go="practice">Choose level</button></div></div><div class="hero-card mascot-card"><div class="mascot">🐑📖</div><div class="wolf-peek">🐺</div><h3>Your reading pasture</h3><p>100 starter readings. No account. Your progress stays on this device.</p><div class="mini-stats"><div class="mini-stat"><strong>${s.done}</strong><span>completed</span></div><div class="mini-stat"><strong>${s.acc}%</strong><span>accuracy</span></div><div class="mini-stat"><strong>${s.vocab}</strong><span>vocab learned</span></div></div></div></section><div class="section-head"><div><h2>Choose your trail</h2><p>Difficulty rises through text length, vocabulary density and inference.</p></div></div><div class="level-grid">${Object.entries(LEVELS).map(([n,l])=>`<button class="level-card" data-level="${n}"><span class="icon">${l.icon}</span><h3>Level ${n} · ${l.name}</h3><p>${l.desc}</p><span class="chip">${state.readings.filter(r=>r.level==n).length} readings</span></button>`).join('')}</div>`;bindCommon()}
function practiceHub(){app.innerHTML=`<div class="section-head"><div><h2>Practice Reading</h2><p>Select a level or continue with an unfinished reading.</p></div><div class="toolbar"><button class="btn primary" id="randomAny">Random reading</button></div></div><div class="level-grid">${Object.entries(LEVELS).map(([n,l])=>{let rs=state.readings.filter(r=>r.level==n),done=rs.filter(r=>state.progress[r.id]?.attempts).length;return `<button class="level-card" data-level="${n}"><span class="icon">${l.icon}</span><h3>Level ${n} · ${l.name}</h3><p>${l.desc}</p><div class="progress-line"><span style="width:${rs.length?done/rs.length*100:0}%"></span></div><span class="chip">${done}/${rs.length} completed</span></button>`}).join('')}</div><div class="wolf-note"><b>🐺 Wolf Question:</b> inference and purpose questions ask you to reason from the passage, not simply match identical words.</div>`;bindCommon();document.getElementById('randomAny').onclick=()=>openReading(pickReading())}
function pickReading(level){let pool=state.readings.filter(r=>!level||r.level==level);let un=pool.filter(r=>!state.progress[r.id]?.attempts);return (un.length?un:pool)[Math.floor(Math.random()*(un.length?un.length:pool.length))]}
function openReading(r){if(!r)return toast('No reading available');currentId=r.id;answers={};hintsUsed={};checked=false;state.lastReading=r.id;save();view='reading';render();window.scrollTo({top:0,behavior:'smooth'})}
function readingView(){let r=state.readings.find(x=>x.id===currentId)||state.readings.find(x=>x.id===state.lastReading)||state.readings[0];if(!r){view='bank';return render()}currentId=r.id;let l=LEVELS[r.level];let wc=r.passage.trim().split(/\s+/).length;app.innerHTML=`<div class="reading-layout"><article class="reading-card"><div class="reading-head"><div><span class="eyebrow">${l.icon} Level ${r.level} · ${l.name}</span><h1>${esc(r.title)}</h1><div class="reading-meta"><span class="chip">${esc(r.category||'Reading')}</span><span class="chip">${wc} words</span><span class="chip">${r.questions.length} questions</span></div></div><button class="btn ghost" data-go="practice">← Levels</button></div><div class="passage">${esc(r.passage)}</div><div class="questions">${r.questions.map((q,i)=>questionHTML(q,i)).join('')}</div><div id="summary"></div><div class="practice-actions"><button class="btn" id="nextBtn">Skip / Next</button><button class="btn primary" id="checkBtn">Check answers</button></div></article><aside class="panel side-panel"><h3>Vocabulary Barn</h3><p style="color:var(--muted);font-size:12px">Open a word only when you need it.</p><div class="vocab-mini">${(r.vocabulary||[]).map((v,i)=>`<button data-vocab-mini="${i}"><b>${esc(v.word)}</b><br><span style="color:var(--muted);font-size:11px">Tap for meaning</span></button>`).join('')||'<span class="chip">No saved vocabulary</span>'}</div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Reading rule</h3><p style="font-size:12px;line-height:1.6;color:var(--muted)">Answer from the passage. After checking, compare your reasoning with the evidence instead of memorizing the option letter.</p></aside></div>`;
bindCommon();document.getElementById('checkBtn').onclick=checkAnswers;document.getElementById('nextBtn').onclick=()=>openReading(pickReading(r.level));document.querySelectorAll('input[type=radio]').forEach(x=>x.onchange=()=>{answers[+x.dataset.q]=x.value==='x'?null:+x.value});document.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>showHint(+b.dataset.hint));document.querySelectorAll('[data-vocab-mini]').forEach(b=>b.onclick=()=>showVocab(r,+b.dataset.vocabMini))}
function questionHTML(q,i){let isWolf=['inference','purpose'].includes(q.type);return `<section class="question-card" id="q${i}"><div class="qtop"><span class="qnum">${isWolf?'🐺':'🐑'} Question ${i+1}</span><span class="qtype">${esc(q.type)}</span></div><h3>${esc(q.question)}</h3><div class="options">${q.options.map((o,j)=>`<label class="option" data-opt="${i}-${j}"><input type="radio" name="q${i}" data-q="${i}" value="${j}"> <span>${String.fromCharCode(65+j)}. ${esc(o)}</span></label>`).join('')}<label class="option"><input type="radio" name="q${i}" data-q="${i}" value="x"> <span>Not sure</span></label></div><div class="hintbar"><button class="hint-btn" data-hint="${i}">💡 Hint</button><span class="hint-text" id="hint${i}">${hintsUsed[i]?esc(q.hints[hintsUsed[i]-1]):'Hints reduce the maximum score for this question.'}</span></div><div id="qr${i}"></div></section>`}
function showHint(i){let r=state.readings.find(x=>x.id===currentId),q=r.questions[i];hintsUsed[i]=Math.min(3,(hintsUsed[i]||0)+1);document.getElementById('hint'+i).textContent=q.hints[hintsUsed[i]-1];sfx('tick')}
function checkAnswers(){if(checked)return;checked=true;let r=state.readings.find(x=>x.id===currentId),points=0,max=r.questions.length;r.questions.forEach((q,i)=>{let selected=answers[i],correct=selected===q.answer;let penalty=[1,.85,.65,.4][hintsUsed[i]||0];if(correct)points+=penalty;document.querySelectorAll(`[data-opt^="${i}-"]`).forEach(el=>{let j=+el.dataset.opt.split('-')[1];if(j===q.answer)el.classList.add('correct');else if(selected===j)el.classList.add('wrong')});let ans=selected==null?'Not sure':q.options[selected];document.getElementById('qr'+i).innerHTML=`<div class="question-result"><b>${correct?'✓ Correct':'✗ Review this one'}</b><br>Your answer: ${esc(ans)}<br><b>Explanation:</b> ${esc(q.explanation)}<div class="evidence"><b>Evidence:</b> “${esc(q.evidence)}”</div></div>`});let p=state.progress[r.id]||{attempts:0,points:0,maxPoints:0,best:0};p.attempts++;p.points+=points;p.maxPoints+=max;p.best=Math.max(p.best,Math.round(points/max*100));state.progress[r.id]=p;state.history.unshift({id:r.id,title:r.title,date:new Date().toISOString(),score:Math.round(points/max*100)});state.history=state.history.slice(0,60);updateStreak();save();document.getElementById('summary').innerHTML=`<div class="result-summary"><strong>${Math.round(points/max*100)}%</strong><div><b>${points.toFixed(2)} / ${max} points</b><br><span style="color:var(--muted)">Hint-adjusted score. Review the evidence under every item.</span></div></div>`;document.getElementById('checkBtn').disabled=true;sfx(points/max>=.7?'good':'bad');document.getElementById('summary').scrollIntoView({behavior:'smooth',block:'center'})}
function updateStreak(){let today=new Date().toISOString().slice(0,10);if(state.lastStudyDate===today)return;let y=new Date(Date.now()-86400000).toISOString().slice(0,10);state.streak=state.lastStudyDate===y?(state.streak||0)+1:1;state.lastStudyDate=today}
function showVocab(r,i){let v=r.vocabulary[i];modal.classList.remove('hidden');modalBody.innerHTML=`<h2>${esc(v.word)}</h2><p><b>Indonesia:</b> ${esc(v.indonesian||'-')}</p><p><b>Meaning:</b> ${esc(v.meaning||'-')}</p><div class="modal-actions"><button class="btn" id="closeM">Close</button><button class="btn primary" id="learnV">${state.learnedVocab[v.word]?'Learned ✓':'Mark as learned'}</button></div>`;document.getElementById('closeM').onclick=closeModal;document.getElementById('learnV').onclick=()=>{state.learnedVocab[v.word]=true;save();toast('Vocabulary saved');closeModal()}}
function bankView(){app.innerHTML=`<div class="section-head"><div><h2>Reading Bank</h2><p>${state.readings.length} passages. Create, edit, duplicate or delete.</p></div><div class="toolbar"><input id="search" placeholder="Search title or text..."><select id="levelFilter"><option value="">All levels</option>${[1,2,3,4].map(n=>`<option value="${n}">Level ${n}</option>`).join('')}</select><button class="btn primary" id="addReading">+ Add Reading</button></div></div><div class="toolbar" style="margin-bottom:14px"><button class="btn" id="exportBtn">Export JSON</button><button class="btn" id="importBtn">Import JSON</button><button class="btn danger" id="resetBtn">Reset starter bank</button></div><div id="bankList" class="bank-list"></div>`;bindCommon();const draw=()=>{let q=document.getElementById('search').value.toLowerCase(),lv=document.getElementById('levelFilter').value;let rows=state.readings.filter(r=>(!lv||r.level==lv)&&(!q||(r.title+' '+r.passage).toLowerCase().includes(q)));document.getElementById('bankList').innerHTML=rows.map(r=>`<div class="bank-card"><div><h3>${esc(r.title)}</h3><p>${LEVELS[r.level].icon} Level ${r.level} · ${esc(r.category||'Reading')} · ${r.passage.split(/\s+/).length} words · ${r.questions.length} questions</p><p style="margin-top:8px">${esc(r.passage.slice(0,180))}${r.passage.length>180?'…':''}</p></div><div class="card-actions"><button class="icon-btn" data-open="${r.id}" title="Open">▶</button><button class="icon-btn" data-edit="${r.id}" title="Edit">✎</button><button class="icon-btn" data-copy="${r.id}" title="Duplicate">⧉</button><button class="icon-btn" data-del="${r.id}" title="Delete">🗑</button></div></div>`).join('')||'<div class="empty">No readings found.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openReading(state.readings.find(r=>r.id===b.dataset.open)));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editReading(b.dataset.edit));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>duplicateReading(b.dataset.copy));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>deleteReading(b.dataset.del))};draw();document.getElementById('search').oninput=draw;document.getElementById('levelFilter').onchange=draw;document.getElementById('addReading').onclick=()=>editReading();document.getElementById('exportBtn').onclick=exportData;document.getElementById('importBtn').onclick=()=>document.getElementById('importFile').click();document.getElementById('resetBtn').onclick=()=>{if(confirm('Restore the 100 starter readings? Custom bank edits will be replaced.')){state.readings=structuredClone(STARTER_READINGS);state.progress={};state.history=[];save();render();toast('Starter bank restored')}}}
function editReading(id){let old=state.readings.find(r=>r.id===id);let r=old?structuredClone(old):{id:'custom-'+Date.now(),title:'',level:1,category:'Custom',passage:'',questions:[blankQ()],vocabulary:[]};modal.classList.remove('hidden');modalBody.innerHTML=`<h2>${old?'Edit':'Add'} Reading</h2><div class="form-grid"><label>Title<input id="fTitle" value="${esc(r.title)}"></label><label>Level<select id="fLevel">${[1,2,3,4].map(n=>`<option value="${n}" ${r.level==n?'selected':''}>Level ${n} · ${LEVELS[n].name}</option>`).join('')}</select></label><label>Category<input id="fCat" value="${esc(r.category||'')}"></label><label>Passage<textarea id="fPass" rows="9">${esc(r.passage)}</textarea></label><div><b>Questions</b><div id="qEditor" class="q-editor"></div><button class="btn" id="addQ" type="button">+ Add question</button></div><div><b>Vocabulary</b><div id="vEditor" class="v-editor"></div><button class="btn" id="addV" type="button">+ Add vocabulary</button></div></div><div class="modal-actions"><button class="btn" id="cancelM">Cancel</button><button class="btn primary" id="saveR">Save Reading</button></div>`;let qs=r.questions,vs=r.vocabulary||[];const drawQ=()=>{document.getElementById('qEditor').innerHTML=qs.map((q,i)=>qEditorHTML(q,i)).join('');document.querySelectorAll('[data-rmq]').forEach(b=>b.onclick=()=>{qs.splice(+b.dataset.rmq,1);drawQ()})};const drawV=()=>{document.getElementById('vEditor').innerHTML=vs.map((v,i)=>`<div class="v-edit-card q-edit-grid"><label>Word<input data-v="word" data-vi="${i}" value="${esc(v.word)}"></label><label>Indonesian<input data-v="indonesian" data-vi="${i}" value="${esc(v.indonesian||'')}"></label><label class="wide">Meaning<input data-v="meaning" data-vi="${i}" value="${esc(v.meaning||'')}"></label><button class="btn danger" data-rmv="${i}" type="button">Remove</button></div>`).join('');document.querySelectorAll('[data-rmv]').forEach(b=>b.onclick=()=>{syncEditors();vs.splice(+b.dataset.rmv,1);drawV()})};drawQ();drawV();document.getElementById('addQ').onclick=()=>{syncEditors();qs.push(blankQ());drawQ()};document.getElementById('addV').onclick=()=>{syncEditors();vs.push({word:'',indonesian:'',meaning:''});drawV()};document.getElementById('cancelM').onclick=closeModal;document.getElementById('saveR').onclick=()=>{syncEditors();r.title=document.getElementById('fTitle').value.trim();r.level=+document.getElementById('fLevel').value;r.category=document.getElementById('fCat').value.trim();r.passage=document.getElementById('fPass').value.trim();r.questions=qs;r.vocabulary=vs.filter(v=>v.word.trim());if(!r.title||!r.passage||!r.questions.length)return toast('Title, passage and at least one question are required');if(r.questions.some(q=>!q.question.trim()||q.options.some(x=>!x.trim())))return toast('Complete every question and option');if(old)state.readings[state.readings.findIndex(x=>x.id===id)]=r;else state.readings.unshift(r);save();closeModal();render();toast('Reading saved')};function syncEditors(){document.querySelectorAll('[data-qfield]').forEach(el=>{let i=+el.dataset.qi,f=el.dataset.qfield;if(f.startsWith('opt'))qs[i].options[+f.slice(3)]=el.value;else if(f==='answer')qs[i].answer=+el.value;else if(f.startsWith('hint'))qs[i].hints[+f.slice(4)]=el.value;else qs[i][f]=el.value});document.querySelectorAll('[data-v]').forEach(el=>{let i=+el.dataset.vi;vs[i][el.dataset.v]=el.value})}}
function qEditorHTML(q,i){return `<div class="q-edit-card q-edit-grid"><label class="wide">Question<input data-qfield="question" data-qi="${i}" value="${esc(q.question)}"></label><label>Type<select data-qfield="type" data-qi="${i}">${['detail','main idea','sequence','inference','purpose','reference','vocabulary'].map(t=>`<option ${q.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Correct<select data-qfield="answer" data-qi="${i}">${[0,1,2,3].map(n=>`<option value="${n}" ${q.answer===n?'selected':''}>${String.fromCharCode(65+n)}</option>`).join('')}</select></label>${[0,1,2,3].map(n=>`<label>Option ${String.fromCharCode(65+n)}<input data-qfield="opt${n}" data-qi="${i}" value="${esc(q.options[n]||'')}"></label>`).join('')}<label class="wide">Explanation<textarea data-qfield="explanation" data-qi="${i}" rows="2">${esc(q.explanation||'')}</textarea></label><label class="wide">Evidence<textarea data-qfield="evidence" data-qi="${i}" rows="2">${esc(q.evidence||'')}</textarea></label>${[0,1,2].map(n=>`<label class="wide">Hint ${n+1}<input data-qfield="hint${n}" data-qi="${i}" value="${esc(q.hints?.[n]||'')}"></label>`).join('')}<button class="btn danger" type="button" data-rmq="${i}">Remove question</button></div>`}
function blankQ(){return{question:'',options:['','','',''],answer:0,type:'detail',evidence:'',explanation:'',hints:['','','']}}
function duplicateReading(id){let r=structuredClone(state.readings.find(x=>x.id===id));r.id='copy-'+Date.now();r.title+=' (Copy)';state.readings.unshift(r);save();render();toast('Reading duplicated')}
function deleteReading(id){if(!confirm('Delete this reading?'))return;state.readings=state.readings.filter(r=>r.id!==id);delete state.progress[id];save();render();toast('Reading deleted')}
function vocabView(){let map=new Map();state.readings.forEach(r=>(r.vocabulary||[]).forEach(v=>{let k=v.word.toLowerCase();if(!map.has(k))map.set(k,{...v,count:0,examples:[]});let x=map.get(k);x.count++;if(x.examples.length<2)x.examples.push(r.title)}));let arr=[...map.values()].sort((a,b)=>a.word.localeCompare(b.word));app.innerHTML=`<div class="section-head"><div><h2>Vocabulary Barn</h2><p>${arr.length} contextual words collected from your Reading Bank.</p></div><div class="toolbar"><input id="vSearch" placeholder="Search vocabulary..."></div></div><div id="vGrid" class="vocab-grid"></div>`;bindCommon();const draw=()=>{let q=document.getElementById('vSearch').value.toLowerCase();document.getElementById('vGrid').innerHTML=arr.filter(v=>(v.word+' '+v.indonesian+' '+v.meaning).toLowerCase().includes(q)).map(v=>`<div class="vocab-card"><h3>${esc(v.word)}</h3><div class="meaning">${esc(v.indonesian||'')}</div><p>${esc(v.meaning||'')}</p><p>Appears in ${v.count} reading${v.count>1?'s':''}.</p><button class="btn ${state.learnedVocab[v.word]?'':'primary'}" data-learn="${esc(v.word)}">${state.learnedVocab[v.word]?'Learned ✓':'Mark learned'}</button></div>`).join('')||'<div class="empty">No vocabulary found.</div>';document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{state.learnedVocab[b.dataset.learn]=!state.learnedVocab[b.dataset.learn];save();draw()})};draw();document.getElementById('vSearch').oninput=draw}
function progressView(){let s=stats();app.innerHTML=`<div class="section-head"><div><h2>Progress</h2><p>Your results are stored locally in this browser.</p></div></div><div class="stats-grid"><div class="stat-card"><strong>${s.done}</strong><span>Readings completed</span></div><div class="stat-card"><strong>${s.acc}%</strong><span>Overall accuracy</span></div><div class="stat-card"><strong>${state.streak||0}</strong><span>Day streak</span></div><div class="stat-card"><strong>${s.vocab}</strong><span>Vocabulary learned</span></div></div><div class="panel" style="padding:22px;margin-top:18px"><h3>Progress by level</h3><div class="level-progress">${[1,2,3,4].map(n=>{let rs=state.readings.filter(r=>r.level==n),done=rs.filter(r=>state.progress[r.id]?.attempts).length,p=rs.length?done/rs.length*100:0;return `<div class="level-row"><b>${LEVELS[n].icon} ${LEVELS[n].name}</b><div class="bar"><span style="width:${p}%"></span></div><span>${done}/${rs.length}</span></div>`}).join('')}</div></div><div class="section-head"><div><h2>Recent sessions</h2></div></div><div class="bank-list">${state.history.slice(0,12).map(h=>`<div class="bank-card"><div><h3>${esc(h.title)}</h3><p>${new Date(h.date).toLocaleString()} · Score ${h.score}%</p></div></div>`).join('')||'<div class="empty">Complete a reading to start your history.</div>'}</div>`;bindCommon()}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='reading-pasture-backup.json';a.click();URL.revokeObjectURL(a.href)}
document.getElementById('importFile').addEventListener('change',e=>{let f=e.target.files[0];if(!f)return;let rd=new FileReader();rd.onload=()=>{try{let x=JSON.parse(rd.result);if(!Array.isArray(x.readings))throw 0;state=x;save();render();toast('Backup imported')}catch(err){toast('Invalid backup file')}};rd.readAsText(f);e.target.value=''})
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML=''};modal.addEventListener('click',e=>{if(e.target===modal)closeModal()})
function bindCommon(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render()});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>openReading(pickReading(+b.dataset.level)));let d=document.getElementById('dailyBtn');if(d)d.onclick=()=>openReading(pickReading())}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});
let audioCtx=null,musicTimer=null;function ensureAudio(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume()}
function tone(freq,dur=.08,vol=.035,type='sine'){if(!settings.sfx&&dur<.3)return;ensureAudio();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=vol;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.stop(audioCtx.currentTime+dur)}
function sfx(kind){if(!settings.sfx)return;if(kind==='good'){tone(523,.12);setTimeout(()=>tone(659,.16),80)}else if(kind==='bad')tone(180,.18,.03,'triangle');else tone(420,.05,.018)}
function musicStart(){if(!settings.music)return;ensureAudio();musicStop();let notes=[261.6,329.6,392,329.6,293.7,349.2,440,349.2],i=0;musicTimer=setInterval(()=>{if(!settings.music)return;toneMusic(notes[i++%notes.length])},900)}
function toneMusic(freq){ensureAudio();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.008;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.55);o.stop(audioCtx.currentTime+.56)}function musicStop(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}}
document.getElementById('themeBtn').onclick=()=>{settings.theme=settings.theme==='light'?'dark':'light';document.documentElement.dataset.theme=settings.theme;save();updateControls()};document.getElementById('sfxBtn').onclick=()=>{settings.sfx=!settings.sfx;save();updateControls();if(settings.sfx)sfx('good')};document.getElementById('musicBtn').onclick=()=>{settings.music=!settings.music;save();updateControls();settings.music?musicStart():musicStop()};document.addEventListener('pointerdown',()=>{if(settings.music&&!musicTimer)musicStart()},{once:true});
render();
